import{_ as o,a0 as u,w as e,s,ao as n,I as r,x as l,a1 as p,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"使用這些去重加密工具來備份你的數據 | LCTT x X-CMD","titleTemplate":false,"description":"使用這些去重加密工具來備份你的數據 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用這些去重加密工具來備份你的數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用這些去重加密工具來備份你的數據 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150629 Backup with these DeDuplicating Encryption Tools","title":"使用這些去重加密工具來備份你的數據","tag":"201507","desc":""},"relativePath":"201507/20150629 Backup with these DeDuplicating Encryption Tools.md","filePath":"[post].md"}'),d={name:"201507/20150629 Backup with these DeDuplicating Encryption Tools.md"};function b(T,i,f,g,m,S){const t=u("Link");return e(),s("div",null,[i[23]||(i[23]=n('<h1 id="使用這些去重加密工具來備份你的數據" tabindex="-1">使用這些去重加密工具來備份你的數據 <a class="header-anchor" href="#使用這些去重加密工具來備份你的數據" aria-label="Permalink to “使用這些去重加密工具來備份你的數據”">​</a></h1><p>無論是體積還是價值，數據都在不斷增長。快速而可靠地備份和恢復數據正變得越來越重要。社會已經適應了技術的廣泛使用，並懂得了如何依靠電腦和移動設備，但很少有人能夠面對丟失重要數據的現實。在遭受數據損失的公司中，30% 的公司將在一年內損失一半市值，70% 的公司將在五年內停止交易。這更加凸顯了數據的價值。</p><p>隨着數據在體積上的增長，提高存儲利用率尤為重要。從計算機的角度説，數據去重是一種特別的數據壓縮技術，因為它可以消除重複數據的拷貝，所以這個技術可以提高存儲利用率。</p><p>數據並不僅僅只有其創造者感興趣。政府、競爭者、犯罪分子、偷窺者可能都熱衷於獲取你的數據。他們或許想偷取你的數據，從你那裏進行敲詐，或看你正在做什麼。因此，對於保護你的數據，加密是非常必要的。</p><p>所以，解決方法是我們需要一個可以去重的加密備份軟件。</p><p>對於所有的用户而言，做文件備份是一件非常必要的事，至今為止許多用户還沒有采取足夠的措施來保護他們的數據。一台電腦不論是工作在一個合作的環境中，還是供私人使用，機器的硬盤可能在沒有任何警告的情況下掛掉。另外，有些數據丟失可能是人為的錯誤所引發的。如果沒有做經常性的備份，數據也可能不可避免地丟失，即使請了專業的數據恢復公司來幫忙。</p><p>這篇文章將對 6 個去重加密備份工具進行簡要的介紹。</p><h3 id="attic" tabindex="-1">Attic <a class="header-anchor" href="#attic" aria-label="Permalink to “Attic”">​</a></h3><p>Attic 是一個可用於去重、加密，驗證完整性的壓縮備份程序，它是用 Python 寫的。Attic 的主要目標是提供一個高效且安全的方式來備份數據。Attic 使用的數據去重技術使得它適用於每日備份，因為只需存儲改變的數據。</p><p>其特點有:</p><ul><li>易用</li><li>可高效利用存儲空間，通過檢查冗餘的數據，對可變塊大小的去重可以減少存儲所用的空間</li><li>可選的數據加密，使用 256 位的 AES 加密算法。數據的完整性和可靠性使用 HMAC-SHA256 來校驗</li><li>使用 SDSH 來進行離線備份</li><li>備份可作為文件系統來掛載</li></ul>',11)),r("p",null,[i[1]||(i[1]=l("網站: ",-1)),p(t,{href:"https://attic-backup.org/"},{default:a(()=>[...i[0]||(i[0]=[l("attic-backup.org",-1)])]),_:1})]),i[24]||(i[24]=n('<h3 id="borg" tabindex="-1">Borg <a class="header-anchor" href="#borg" aria-label="Permalink to “Borg”">​</a></h3><p>Borg 是 Attic 的一個分支。它是一個安全的開源備份程序，被設計用來高效地存儲那些新的或修改過的數據。</p><p>Borg 的主要目標是提供一個高效、安全的方式來存儲數據。Borg 使用的數據去重技術使得它適用於每日備份，因為只需存儲改變的數據。認證加密使得它適用於存儲在不完全可信的位置。</p><p>Borg 由 Python 寫成。Borg 於 2015 年 5 月被創造出來，是為了解決讓新的代碼或重大的改變帶入 Attic 的困難。</p><p>其特點包括:</p><ul><li>易用</li><li>可高效利用存儲空間，通過檢查冗餘的數據，對可變塊大小的去重被用來減少存儲所用的空間</li><li>可選的數據加密，使用 256 位的 AES 加密算法。數據的完整性和可靠性使用 HMAC-SHA256 來校驗</li><li>使用 SDSH 來進行離線備份</li><li>備份可作為文件系統來掛載</li></ul><p>Borg 與 Attic 不兼容。</p>',7)),r("p",null,[i[3]||(i[3]=l("網站: ",-1)),p(t,{href:"https://borgbackup.github.io/borgbackup/"},{default:a(()=>[...i[2]||(i[2]=[l("borgbackup.github.io/borgbackup",-1)])]),_:1})]),i[25]||(i[25]=n('<h3 id="obnam" tabindex="-1">Obnam <a class="header-anchor" href="#obnam" aria-label="Permalink to “Obnam”">​</a></h3><p>Obnam (OBligatory NAMe) 是一個易用、安全的基於 Python 的備份程序。備份可被存儲在本地硬盤或通過 SSH SFTP 協議存儲到網上。若使用了備份服務器，它並不需要任何特殊的軟件，只需要使用 SSH 即可。</p><p>Obnam 通過將數據分成數據塊，並單獨存儲它們來達到去重的目的，每次通過增量備份來生成備份，每次備份的生成就像是一次新的快照，但事實上是真正的增量備份。Obnam 由 Lars Wirzenius 開發。</p><p>其特點有:</p><ul><li>易用</li><li>快照備份</li><li>數據去重，跨文件，然後生成備份</li><li>可使用 GnuPG 來加密備份</li><li>向一個單獨的倉庫中備份多個客户端的數據</li><li>備份檢查點 (創建一個保存點，以每 100MB 或其他容量)</li><li>包含多個選項來調整性能，包括調整 lru-size 或 upload-queue-size</li><li>支持 MD5 校驗算法來識別重複的數據塊</li><li>通過 SFTP 將備份存儲到一個服務器上</li><li>同時支持 push(即在客户端上運行) 和 pull(即在服務器上運行)</li></ul>',5)),r("p",null,[i[5]||(i[5]=l("網站: ",-1)),p(t,{href:"http://obnam.org/"},{default:a(()=>[...i[4]||(i[4]=[l("obnam.org",-1)])]),_:1})]),i[26]||(i[26]=n('<h3 id="duplicity" tabindex="-1">Duplicity <a class="header-anchor" href="#duplicity" aria-label="Permalink to “Duplicity”">​</a></h3><p>Duplicity 以 tar 文件格式增量備份文件和目錄，並使用 GnuPG 來進行加密，同時將它們上傳到遠程(或本地)的文件服務器上。它可以使用 ssh/scp、本地文件獲取、rsync、 ftp 和 Amazon S3 等來傳遞數據。</p><p>因為 duplicity 使用了 librsync， 增量存檔可以高效地利用存儲空間，且只記錄自從上次備份依賴改變的那部分文件。由於該軟件使用 GnuPG 來加密或對這些歸檔文件進行進行簽名，這使得它們免於服務器的監視或修改。</p><p>當前 duplicity 支持備份刪除的文件，全部的 unix 權限，目錄，符號鏈接， fifo 等。</p><p>duplicity 軟件包還包含有 rdiffdir 工具。 Rdiffdir 是 librsync 的 rdiff 針對目錄的擴展。它可以用來生成對目錄的簽名和差異，對普通文件也有效。</p><p>其特點有:</p><ul><li>使用簡單</li><li>對歸檔進行加密和簽名(使用 GnuPG)</li><li>高效使用帶寬和存儲空間，使用 rsync 的算法</li><li>標準的文件格式</li><li>可選擇多種遠程協議 <ul><li>本地存儲</li><li>scp/ssh</li><li>ftp</li><li>rsync</li><li>HSI</li><li>WebDAV</li><li>Amazon S3</li></ul></li></ul>',7)),r("p",null,[i[7]||(i[7]=l("網站: ",-1)),p(t,{href:"http://duplicity.nongnu.org/"},{default:a(()=>[...i[6]||(i[6]=[l("duplicity.nongnu.org",-1)])]),_:1})]),i[27]||(i[27]=n('<h3 id="zbackup" tabindex="-1">ZBackup <a class="header-anchor" href="#zbackup" aria-label="Permalink to “ZBackup”">​</a></h3><p>ZBackup 是一個通用的全局去重備份工具。</p><p>其特點包括:</p><ul><li>對存儲數據並行進行 LZMA 或 LZO 壓縮，在一個倉庫中，你還可以混合使用 LZMA 和 LZO</li><li>內置對存儲數據的 AES 加密</li><li>能夠刪除舊的備份數據</li><li>可以使用 64 位的滾動哈希算法，使得文件衝突的數量幾乎為零</li><li>倉庫中存儲的文件是不可修改的，已備份的文件不會被修改。</li><li>用 C++ 寫成，只需少量的庫文件依賴</li><li>在生成環境中可以安全使用</li><li>可以在不同倉庫中進行數據交換而不必再進行壓縮</li><li>使用 64 位改進型 Rabin-Karp 滾動哈希算法</li></ul>',4)),r("p",null,[i[9]||(i[9]=l("網站: ",-1)),p(t,{href:"http://zbackup.org/"},{default:a(()=>[...i[8]||(i[8]=[l("zbackup.org",-1)])]),_:1})]),i[28]||(i[28]=n('<h3 id="bup" tabindex="-1">bup <a class="header-anchor" href="#bup" aria-label="Permalink to “bup”">​</a></h3><p>bup 是一個用 Python 寫的備份程序，其名稱是 &quot;backup&quot; 的縮寫。基於 git packfile 文件格式， bup 提供了一個高效的方式來備份一個系統，提供快速的增量備份和全局去重(在文件中或文件裏，甚至包括虛擬機鏡像)。</p><p>bup 在 LGPL 版本 2 協議下發行。</p><p>其特點包括:</p><ul><li>全局去重 (在文件之間或文件內部，甚至包括虛擬機鏡像)</li><li>使用一個滾動的校驗和算法(類似於 rsync) 來將大文件分為多個數據塊</li><li>使用來自 git 的 packfile 文件格式</li><li>直接寫入 packfile 文件，以此提供快速的增量備份</li><li>可以使用 &quot;par2&quot; 冗餘來恢復衝突的備份</li><li>可以作為一個 FUSE 文件系統來掛載你的 bup 倉庫</li></ul>',5)),r("p",null,[i[11]||(i[11]=l("網站: ",-1)),p(t,{href:"https://bup.github.io/"},{default:a(()=>[...i[10]||(i[10]=[l("bup.github.io",-1)])]),_:1})]),i[29]||(i[29]=r("hr",null,null,-1)),r("p",null,[i[13]||(i[13]=l("via: ",-1)),p(t,{href:"http://www.linuxlinks.com/article/20150628060000607/BackupTools.html"},{default:a(()=>[...i[12]||(i[12]=[l("http://www.linuxlinks.com/article/20150628060000607/BackupTools.html",-1)])]),_:1})]),r("p",null,[i[16]||(i[16]=l("譯者：",-1)),p(t,{href:"https://github.com/FSSlc"},{default:a(()=>[...i[14]||(i[14]=[l("FSSlc",-1)])]),_:1}),i[17]||(i[17]=l(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[15]||(i[15]=[l("wxy",-1)])]),_:1})]),r("p",null,[i[20]||(i[20]=l("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[18]||(i[18]=[l("LCTT",-1)])]),_:1}),i[21]||(i[21]=l(" 原創翻譯，",-1)),p(t,{href:"https://linux.cn/"},{default:a(()=>[...i[19]||(i[19]=[l("Linux中國",-1)])]),_:1}),i[22]||(i[22]=l(" 榮譽推出",-1))])])}const P=o(d,[["render",b]]);export{k as __pageData,P as default};
